import{_ as e,o as t,c as s,a0 as r}from"./chunks/framework.CShDTZbC.js";const h=JSON.parse('{"title":"Phase 1: Problem Discovery - 30 Candidate Problems","description":"","frontmatter":{},"headers":[],"relativePath":"internals/hackathon-archive/problem-candidates.md","filePath":"internals/hackathon-archive/problem-candidates.md"}'),n={name:"internals/hackathon-archive/problem-candidates.md"};function o(a,i,l,g,c,d){return t(),s("div",null,[...i[0]||(i[0]=[r('<h1 id="phase-1-problem-discovery-30-candidate-problems" tabindex="-1">Phase 1: Problem Discovery - 30 Candidate Problems <a class="header-anchor" href="#phase-1-problem-discovery-30-candidate-problems" aria-label="Permalink to &quot;Phase 1: Problem Discovery - 30 Candidate Problems&quot;">​</a></h1><p>This document contains approximately 30 candidate problems across various domains. Each candidate is evaluated against the 14 required dimensions to assess its viability for the Micro1 Hackathon.</p><hr><h2 id="domain-software-engineering-devops" tabindex="-1">Domain: Software Engineering &amp; DevOps <a class="header-anchor" href="#domain-software-engineering-devops" aria-label="Permalink to &quot;Domain: Software Engineering &amp; DevOps&quot;">​</a></h2><h3 id="_1-ci-cd-build-failure-investigator" tabindex="-1">1. CI/CD Build Failure Investigator <a class="header-anchor" href="#_1-ci-cd-build-failure-investigator" aria-label="Permalink to &quot;1. CI/CD Build Failure Investigator&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> DevOps / Developers facing cryptic CI/CD pipeline failures.</li><li><strong>Bottleneck:</strong> Digging through thousands of lines of logs to find the root cause (e.g., OOM, network timeout, test failure) is tedious.</li><li><strong>Agentic Necessity:</strong> Needs to read logs, search StackOverflow/internal wikis, inspect recent commits, and propose a fix.</li><li><strong>Baseline:</strong> Simple LLM prompt with the last 100 lines of the build log.</li><li><strong>Primary Metric:</strong> Accuracy of root cause identification (0-100%).</li><li><strong>10+ Cases Feasibility:</strong> High (historical failed GitHub Actions runs).</li><li><strong>Verification:</strong> Compare agent&#39;s proposed fix with the actual PR that fixed the build.</li><li><strong>Data Availability:</strong> Public GitHub repositories with failed action logs.</li><li><strong>Engineering Depth:</strong> Medium-High (parsing large logs, semantic search).</li><li><strong>Reproducibility:</strong> High (logs and commits are immutable).</li><li><strong>Differentiation:</strong> Goes beyond just pointing out the error line; traces it to the specific code change.</li><li><strong>Risks:</strong> Logs can be too large for context windows; hallucinated fixes.</li><li><strong>Demo Potential:</strong> Show a cryptic Jenkins/GH Action failure instantly diagnosed.</li><li><strong>Rubric Strengths/Weaknesses:</strong> Strong on Reproducibility and Baseline comparison. Risk of low End-to-End Quality if fixes are consistently wrong.</li></ul><h3 id="_2-dependency-update-risk-analyzer" tabindex="-1">2. Dependency Update Risk Analyzer <a class="header-anchor" href="#_2-dependency-update-risk-analyzer" aria-label="Permalink to &quot;2. Dependency Update Risk Analyzer&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Engineers updating legacy dependencies (e.g., React 16 to 18) fear breaking changes.</li><li><strong>Bottleneck:</strong> Manually reading changelogs, migration guides, and community issues for dozens of transitive dependencies.</li><li><strong>Agentic Necessity:</strong> Needs to fetch release notes, search GitHub issues for reported regressions, and analyze local AST for deprecated API usage.</li><li><strong>Baseline:</strong> Dependabot (just bumps version and runs existing tests).</li><li><strong>Primary Metric:</strong> Number of breaking changes correctly identified before merge.</li><li><strong>10+ Cases Feasibility:</strong> High (historical major version bumps in open source).</li><li><strong>Verification:</strong> Compare to manual migration PRs and issues.</li><li><strong>Data Availability:</strong> Public GitHub repos, npm/PyPI registries.</li><li><strong>Engineering Depth:</strong> High (AST parsing, web scraping changelogs).</li><li><strong>Reproducibility:</strong> High (using fixed git commits).</li><li><strong>Differentiation:</strong> Predicts runtime/API impact rather than just bumping a text file.</li><li><strong>Risks:</strong> Overwhelming false positives.</li><li><strong>Demo Potential:</strong> Show it catching a deprecated API usage that tests didn&#39;t cover.</li><li><strong>Rubric Strengths/Weaknesses:</strong> Strong User Value. Risk: High latency in searching.</li></ul><h3 id="_3-flaky-test-root-cause-diagnoser" tabindex="-1">3. Flaky Test Root Cause Diagnoser <a class="header-anchor" href="#_3-flaky-test-root-cause-diagnoser" aria-label="Permalink to &quot;3. Flaky Test Root Cause Diagnoser&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> QA/Developers dealing with tests that randomly fail.</li><li><strong>Bottleneck:</strong> Reproducing flaky tests locally is often impossible; requires analyzing timing, shared state, or network calls.</li><li><strong>Agentic Necessity:</strong> Needs to run the test repeatedly, inject delays, analyze traces/logs, and isolate the shared state.</li><li><strong>Baseline:</strong> A script that just reruns the test 10 times and outputs the diff of passing vs failing logs.</li><li><strong>Primary Metric:</strong> Time saved (or % of flaky tests successfully isolated).</li><li><strong>10+ Cases Feasibility:</strong> Medium (finding reproducible flaky tests is hard).</li><li><strong>Verification:</strong> Check if the agent&#39;s proposed fix stops the flakiness over 100 runs.</li><li><strong>Data Availability:</strong> Can create synthetic flaky tests or find known open-source ones.</li><li><strong>Engineering Depth:</strong> Very High (sandbox execution, iterative testing).</li><li><strong>Reproducibility:</strong> Medium (flakiness is non-deterministic by nature).</li><li><strong>Differentiation:</strong> True autonomous debugging loop, highly agentic.</li><li><strong>Risks:</strong> Agent gets stuck in infinite loops; reproducibility is inherently challenging for flaky tests.</li><li><strong>Demo Potential:</strong> Very strong (watching an agent narrow down a race condition).</li><li><strong>Rubric Strengths/Weaknesses:</strong> High Agentic Necessity (30 pts), but Reproducibility (15 pts) could suffer.</li></ul><h3 id="_4-architectural-decision-record-adr-generator" tabindex="-1">4. Architectural Decision Record (ADR) Generator <a class="header-anchor" href="#_4-architectural-decision-record-adr-generator" aria-label="Permalink to &quot;4. Architectural Decision Record (ADR) Generator&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Tech Leads need to document system architecture changes, but rarely have time.</li><li><strong>Bottleneck:</strong> Writing ADRs requires synthesizing PR discussions, Slack threads, and code changes into a formal document.</li><li><strong>Agentic Necessity:</strong> Needs to aggregate context across Jira, GitHub PRs, and code diffs to construct a coherent narrative.</li><li><strong>Baseline:</strong> Basic LLM summarizing a single PR description.</li><li><strong>Primary Metric:</strong> Subjective quality of ADR (graded by senior engineers) or time saved.</li><li><strong>10+ Cases Feasibility:</strong> High (any large PR in an open-source project).</li><li><strong>Verification:</strong> Compare agent-generated ADR to human-written ADR.</li><li><strong>Data Availability:</strong> Public GitHub PRs and issues.</li><li><strong>Engineering Depth:</strong> Medium (data aggregation, prompt chaining).</li><li><strong>Reproducibility:</strong> High.</li><li><strong>Differentiation:</strong> Cross-referencing multiple data sources to find the <em>why</em>, not just the <em>what</em>.</li><li><strong>Risks:</strong> Output might be too generic.</li><li><strong>Demo Potential:</strong> Good, but visually boring (just text generation).</li><li><strong>Rubric Strengths/Weaknesses:</strong> High Reproducibility, but low Agentic Necessity (could just be a RAG prompt).</li></ul><h3 id="_5-api-breaking-change-detector" tabindex="-1">5. API Breaking Change Detector <a class="header-anchor" href="#_5-api-breaking-change-detector" aria-label="Permalink to &quot;5. API Breaking Change Detector&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> API Developers need to ensure they don&#39;t break downstream clients.</li><li><strong>Bottleneck:</strong> Semantic breaking changes (e.g., changing a field&#39;s format from ISO to Unix timestamp) aren&#39;t caught by simple OpenAPI diffs.</li><li><strong>Agentic Necessity:</strong> Needs to analyze code changes, check API schemas, and generate synthetic client requests to test for semantic breaks.</li><li><strong>Baseline:</strong> OpenAPI diff tool (catches structural breaks, misses semantic ones).</li><li><strong>Primary Metric:</strong> Semantic breaking changes caught.</li><li><strong>10+ Cases Feasibility:</strong> High (synthetic or real API changes).</li><li><strong>Verification:</strong> Run downstream client tests against the modified API.</li><li><strong>Data Availability:</strong> Open source APIs (e.g., Stripe API mocks).</li><li><strong>Engineering Depth:</strong> High (generating and executing synthetic tests).</li><li><strong>Reproducibility:</strong> High.</li><li><strong>Differentiation:</strong> Catches logical breaks, not just schema breaks.</li><li><strong>Risks:</strong> Setting up the sandbox environments for 10+ cases is tedious.</li><li><strong>Demo Potential:</strong> Strong (showing a subtle break being caught).</li><li><strong>Rubric Strengths/Weaknesses:</strong> Excellent Measured Improvement potential.</li></ul><h3 id="_6-cloud-cost-anomaly-investigator" tabindex="-1">6. Cloud Cost Anomaly Investigator <a class="header-anchor" href="#_6-cloud-cost-anomaly-investigator" aria-label="Permalink to &quot;6. Cloud Cost Anomaly Investigator&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> FinOps/DevOps engineers seeing a sudden spike in AWS/GCP bills.</li><li><strong>Bottleneck:</strong> Correlating cost spikes in billing dashboards to specific infrastructure changes or code deployments.</li><li><strong>Agentic Necessity:</strong> Needs to query billing APIs, cross-reference with Terraform state, and check recent PRs for infrastructure changes.</li><li><strong>Baseline:</strong> AWS Cost Explorer anomaly alerts (just says &quot;EC2 went up 20%&quot;).</li><li><strong>Primary Metric:</strong> Accuracy of root cause identification.</li><li><strong>10+ Cases Feasibility:</strong> Medium (requires simulated or exported billing/git data).</li><li><strong>Verification:</strong> Compare with known historical billing spikes.</li><li><strong>Data Availability:</strong> Harder (requires anonymized/synthetic billing exports).</li><li><strong>Engineering Depth:</strong> Medium-High (data correlation).</li><li><strong>Reproducibility:</strong> High (if using static CSV/JSON exports).</li><li><strong>Differentiation:</strong> Connects money directly to code.</li><li><strong>Risks:</strong> Data privacy; hard to get 10 realistic cases.</li><li><strong>Demo Potential:</strong> Very strong business value.</li><li><strong>Rubric Strengths/Weaknesses:</strong> High User Value, but Reproducibility might rely on mock data.</li></ul><h3 id="_7-legacy-code-translator-verifier-e-g-cobol-perl-to-python" tabindex="-1">7. Legacy Code Translator &amp; Verifier (e.g., COBOL/Perl to Python) <a class="header-anchor" href="#_7-legacy-code-translator-verifier-e-g-cobol-perl-to-python" aria-label="Permalink to &quot;7. Legacy Code Translator &amp; Verifier (e.g., COBOL/Perl to Python)&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Enterprises migrating legacy systems to modern stacks.</li><li><strong>Bottleneck:</strong> Ensuring the translated code has the exact same business logic and side effects.</li><li><strong>Agentic Necessity:</strong> Needs to translate code, generate unit tests for the old code, run them against the new code, and iteratively fix the translation until tests pass.</li><li><strong>Baseline:</strong> Zero-shot LLM translation (often subtly wrong).</li><li><strong>Primary Metric:</strong> Percentage of test cases passing on the translated code.</li><li><strong>10+ Cases Feasibility:</strong> High (can find/create legacy scripts).</li><li><strong>Verification:</strong> Automated test suite execution.</li><li><strong>Data Availability:</strong> Open-source Perl/Ruby/COBOL scripts.</li><li><strong>Engineering Depth:</strong> High (sandbox execution, iterative feedback loop).</li><li><strong>Reproducibility:</strong> High.</li><li><strong>Differentiation:</strong> The iterative testing loop guarantees functional equivalence.</li><li><strong>Risks:</strong> Infinite loops during fixing.</li><li><strong>Demo Potential:</strong> Excellent (showing the agent fail, write a test, and fix itself).</li><li><strong>Rubric Strengths/Weaknesses:</strong> High across the board (Agentic Necessity, Baseline comparison, Reproducibility).</li></ul><h3 id="_8-database-schema-migration-reviewer" tabindex="-1">8. Database Schema Migration Reviewer <a class="header-anchor" href="#_8-database-schema-migration-reviewer" aria-label="Permalink to &quot;8. Database Schema Migration Reviewer&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> DBAs and Backend engineers reviewing SQL migrations.</li><li><strong>Bottleneck:</strong> Spotting locking issues, missing indices, or destructive data drops in large migrations is error-prone.</li><li><strong>Agentic Necessity:</strong> Needs to run <code>EXPLAIN</code> plans on a shadow database, check table sizes, and predict downtime.</li><li><strong>Baseline:</strong> Simple regex checks (e.g., forbidding <code>DROP TABLE</code>).</li><li><strong>Primary Metric:</strong> Number of performance/locking risks identified.</li><li><strong>10+ Cases Feasibility:</strong> High.</li><li><strong>Verification:</strong> Run the migration on a dummy large database and measure lock times.</li><li><strong>Data Availability:</strong> Synthetic schemas with millions of rows.</li><li><strong>Engineering Depth:</strong> High (spinning up Docker DBs, executing plans).</li><li><strong>Reproducibility:</strong> High.</li><li><strong>Differentiation:</strong> Actually executes the plan rather than just statically analyzing SQL.</li><li><strong>Risks:</strong> Database setup for reproducibility is heavy.</li><li><strong>Demo Potential:</strong> Strong technical demo.</li><li><strong>Rubric Strengths/Weaknesses:</strong> High Engineering Quality.</li></ul><h3 id="_9-accessibility-a11y-web-auditor-fixer" tabindex="-1">9. Accessibility (a11y) Web Auditor &amp; Fixer <a class="header-anchor" href="#_9-accessibility-a11y-web-auditor-fixer" aria-label="Permalink to &quot;9. Accessibility (a11y) Web Auditor &amp; Fixer&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Frontend developers ensuring WCAG compliance.</li><li><strong>Bottleneck:</strong> Axe tools find syntax errors (missing alt text), but cannot judge if the alt text is <em>contextually accurate</em> or if keyboard navigation is logical.</li><li><strong>Agentic Necessity:</strong> Needs to visually inspect the page, navigate via keyboard (Playwright), and propose code fixes.</li><li><strong>Baseline:</strong> Axe-core static analysis.</li><li><strong>Primary Metric:</strong> Semantic accessibility issues resolved.</li><li><strong>10+ Cases Feasibility:</strong> High (any 10 websites).</li><li><strong>Verification:</strong> Manual review of the fixes.</li><li><strong>Data Availability:</strong> Infinite (the web).</li><li><strong>Engineering Depth:</strong> High (Playwright integration, multimodal vision).</li><li><strong>Reproducibility:</strong> Medium (live websites change; better to use saved HTML/CSS snapshots).</li><li><strong>Differentiation:</strong> Multimodal assessment of semantic meaning.</li><li><strong>Risks:</strong> Vision models can be flaky.</li><li><strong>Demo Potential:</strong> Highly visual and impactful.</li><li><strong>Rubric Strengths/Weaknesses:</strong> Great Problem Value and Baseline comparison.</li></ul><h3 id="_10-open-source-license-compliance-checker" tabindex="-1">10. Open Source License Compliance Checker <a class="header-anchor" href="#_10-open-source-license-compliance-checker" aria-label="Permalink to &quot;10. Open Source License Compliance Checker&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Legal/Compliance teams auditing software before a release or acquisition.</li><li><strong>Bottleneck:</strong> Scanning deeply nested transitive dependencies for copyleft (GPL) licenses or conflicting terms.</li><li><strong>Agentic Necessity:</strong> Needs to fetch repos, read custom LICENSE files (not just standard ones), and evaluate risk based on how the library is linked (dynamic vs static).</li><li><strong>Baseline:</strong> Traditional SCA tools (e.g., FOSSA) which fail on custom license text.</li><li><strong>Primary Metric:</strong> Accuracy of license conflict detection.</li><li><strong>10+ Cases Feasibility:</strong> High.</li><li><strong>Verification:</strong> Legal expert review.</li><li><strong>Data Availability:</strong> Open source repos.</li><li><strong>Engineering Depth:</strong> Medium.</li><li><strong>Reproducibility:</strong> High.</li><li><strong>Differentiation:</strong> Can read and understand non-standard, custom-written license files.</li><li><strong>Risks:</strong> A bit boring for a demo.</li><li><strong>Rubric Strengths/Weaknesses:</strong> Low Agentic Necessity (mostly just text classification).</li></ul><hr><h2 id="domain-legal-security-compliance" tabindex="-1">Domain: Legal, Security &amp; Compliance <a class="header-anchor" href="#domain-legal-security-compliance" aria-label="Permalink to &quot;Domain: Legal, Security &amp; Compliance&quot;">​</a></h2><h3 id="_11-security-penetration-testing-report-validator" tabindex="-1">11. Security Penetration Testing Report Validator <a class="header-anchor" href="#_11-security-penetration-testing-report-validator" aria-label="Permalink to &quot;11. Security Penetration Testing Report Validator&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Security teams receiving Pentest reports from external vendors.</li><li><strong>Bottleneck:</strong> Verifying if the reported vulnerabilities are actually exploitable in the current environment (many are false positives).</li><li><strong>Agentic Necessity:</strong> Needs to read the report, run harmless verification scripts (e.g., curl, nmap) in a sandbox, and confirm exploitability.</li><li><strong>Baseline:</strong> Manual verification by an internal security engineer.</li><li><strong>Primary Metric:</strong> False positive reduction rate.</li><li><strong>10+ Cases Feasibility:</strong> Medium (requires safe, vulnerable sandbox apps like OWASP Juice Shop).</li><li><strong>Verification:</strong> Did the agent correctly exploit or debunk the claim?</li><li><strong>Data Availability:</strong> Synthetic vulnerable apps.</li><li><strong>Engineering Depth:</strong> High (safe sandbox orchestration).</li><li><strong>Reproducibility:</strong> High (if using Docker containers).</li><li><strong>Differentiation:</strong> Active verification over passive reading.</li><li><strong>Risks:</strong> High risk of agent breaking things if not sandboxed properly.</li><li><strong>Demo Potential:</strong> Very cool (watching an agent hack a sandbox).</li><li><strong>Rubric Strengths/Weaknesses:</strong> Excellent Agentic Necessity.</li></ul><h3 id="_12-legal-contract-clause-extractor-risk-scorer-msa-nda" tabindex="-1">12. Legal Contract Clause Extractor &amp; Risk Scorer (MSA/NDA) <a class="header-anchor" href="#_12-legal-contract-clause-extractor-risk-scorer-msa-nda" aria-label="Permalink to &quot;12. Legal Contract Clause Extractor &amp; Risk Scorer (MSA/NDA)&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Sales/Legal teams reviewing standard contracts.</li><li><strong>Bottleneck:</strong> Finding non-standard indemnification or liability clauses buried in 50-page PDFs.</li><li><strong>Agentic Necessity:</strong> Needs to cross-reference the document against a company&#39;s &quot;standard playbook&quot; and highlight deviations.</li><li><strong>Baseline:</strong> Simple RAG or zero-shot extraction.</li><li><strong>Primary Metric:</strong> Recall of non-standard clauses.</li><li><strong>10+ Cases Feasibility:</strong> High (public SEC contracts).</li><li><strong>Verification:</strong> Lawyer review.</li><li><strong>Data Availability:</strong> Public EDGAR database.</li><li><strong>Engineering Depth:</strong> Low-Medium.</li><li><strong>Reproducibility:</strong> High.</li><li><strong>Differentiation:</strong> Explains <em>why</em> it deviates from the playbook.</li><li><strong>Risks:</strong> Heavily reliant on base LLM intelligence, low agentic orchestration.</li><li><strong>Demo Potential:</strong> Boring visually.</li><li><strong>Rubric Strengths/Weaknesses:</strong> Weak on Agentic Necessity and Engineering Depth.</li></ul><h3 id="_13-privacy-policy-vs-code-tracker-gdpr-ccpa" tabindex="-1">13. Privacy Policy vs. Code Tracker (GDPR/CCPA) <a class="header-anchor" href="#_13-privacy-policy-vs-code-tracker-gdpr-ccpa" aria-label="Permalink to &quot;13. Privacy Policy vs. Code Tracker (GDPR/CCPA)&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Privacy engineers ensuring apps don&#39;t collect data secretly.</li><li><strong>Bottleneck:</strong> The privacy policy says &quot;We don&#39;t collect location,&quot; but a developer recently added a background GPS tracker.</li><li><strong>Agentic Necessity:</strong> Needs to read the Privacy Policy (text), scan the codebase (AST/imports) for telemetry/tracking SDKs, and flag contradictions.</li><li><strong>Baseline:</strong> Manual audit.</li><li><strong>Primary Metric:</strong> Number of privacy violations caught.</li><li><strong>10+ Cases Feasibility:</strong> High (open source mobile apps).</li><li><strong>Verification:</strong> Manual code review.</li><li><strong>Data Availability:</strong> Open source iOS/Android apps.</li><li><strong>Engineering Depth:</strong> High (cross-modal reasoning: legal text vs code).</li><li><strong>Reproducibility:</strong> High.</li><li><strong>Differentiation:</strong> Bridges the gap between legal and engineering.</li><li><strong>Risks:</strong> Hard to map complex legal text to specific code artifacts.</li><li><strong>Demo Potential:</strong> Strong narrative.</li><li><strong>Rubric Strengths/Weaknesses:</strong> High Problem Value.</li></ul><h3 id="_14-terraform-iac-security-auditor" tabindex="-1">14. Terraform/IaC Security Auditor <a class="header-anchor" href="#_14-terraform-iac-security-auditor" aria-label="Permalink to &quot;14. Terraform/IaC Security Auditor&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Cloud architects ensuring infrastructure is secure before deployment.</li><li><strong>Bottleneck:</strong> Checkov/tfsec catch syntax issues, but miss logical flaws (e.g., an S3 bucket is private, but an IAM role attached to a public EC2 instance has full access to it).</li><li><strong>Agentic Necessity:</strong> Needs to build a graph of the infrastructure, simulate IAM permissions, and find logical attack paths.</li><li><strong>Baseline:</strong> Checkov (static analysis).</li><li><strong>Primary Metric:</strong> Logical attack paths found vs false positives.</li><li><strong>10+ Cases Feasibility:</strong> High (using vulnerable Terraform templates like Terragoat).</li><li><strong>Verification:</strong> Compare against known vulnerabilities in the templates.</li><li><strong>Data Availability:</strong> Open source vulnerable IaC.</li><li><strong>Engineering Depth:</strong> High (graph traversal, IAM simulation).</li><li><strong>Reproducibility:</strong> High.</li><li><strong>Differentiation:</strong> Context-aware security analysis.</li><li><strong>Risks:</strong> Complex to build the infrastructure graph.</li><li><strong>Rubric Strengths/Weaknesses:</strong> Very strong on Baseline comparison (Checkov vs Agent).</li></ul><h3 id="_15-incident-post-mortem-drafter" tabindex="-1">15. Incident Post-Mortem Drafter <a class="header-anchor" href="#_15-incident-post-mortem-drafter" aria-label="Permalink to &quot;15. Incident Post-Mortem Drafter&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> SREs writing incident reports after an outage.</li><li><strong>Bottleneck:</strong> Collating timelines from Slack, Datadog alerts, PagerDuty, and GitHub PRs takes hours.</li><li><strong>Agentic Necessity:</strong> Needs to use APIs to pull timelines from multiple tools, construct a chronological narrative, and draft a blameless post-mortem.</li><li><strong>Baseline:</strong> A human copying and pasting logs into a Google Doc.</li><li><strong>Primary Metric:</strong> Time saved drafting the report.</li><li><strong>10+ Cases Feasibility:</strong> Low-Medium (requires access to real, multi-platform incident data).</li><li><strong>Verification:</strong> Subjective quality check by SREs.</li><li><strong>Data Availability:</strong> Difficult (requires mocking Slack, Datadog, GitHub for 10 cases).</li><li><strong>Engineering Depth:</strong> Medium (mostly API orchestration).</li><li><strong>Reproducibility:</strong> Hard to package for judges without live API keys.</li><li><strong>Risks:</strong> Fails Reproducibility criteria heavily due to mock data complexity.</li><li><strong>Rubric Strengths/Weaknesses:</strong> High User Value, but fails Reproducibility (15 pts).</li></ul><hr><h2 id="domain-research-medical-scientific" tabindex="-1">Domain: Research, Medical &amp; Scientific <a class="header-anchor" href="#domain-research-medical-scientific" aria-label="Permalink to &quot;Domain: Research, Medical &amp; Scientific&quot;">​</a></h2><h3 id="_16-scientific-paper-fact-checker-claims-vs-evidence" tabindex="-1">16. Scientific Paper Fact-Checker (Claims vs Evidence) <a class="header-anchor" href="#_16-scientific-paper-fact-checker-claims-vs-evidence" aria-label="Permalink to &quot;16. Scientific Paper Fact-Checker (Claims vs Evidence)&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Peer reviewers and researchers evaluating new papers.</li><li><strong>Bottleneck:</strong> Verifying if the citations actually support the claims made in the text.</li><li><strong>Agentic Necessity:</strong> Needs to extract claims, fetch the cited papers (PDFs), read the specific sections, and verify if the evidence matches the claim.</li><li><strong>Baseline:</strong> Zero-shot LLM reading just the abstract.</li><li><strong>Primary Metric:</strong> Accuracy in detecting unsupported citations.</li><li><strong>10+ Cases Feasibility:</strong> High (open access papers on ArXiv/PubMed).</li><li><strong>Verification:</strong> Manual verification of citations.</li><li><strong>Data Availability:</strong> High.</li><li><strong>Engineering Depth:</strong> High (multimodal PDF reading, citation graph traversal).</li><li><strong>Reproducibility:</strong> High.</li><li><strong>Differentiation:</strong> Deep verification rather than surface-level summarization.</li><li><strong>Risks:</strong> Paywalled papers will block the agent.</li><li><strong>Demo Potential:</strong> Very strong (showing it catch a hallucinated citation).</li><li><strong>Rubric Strengths/Weaknesses:</strong> High Agentic Necessity and Problem Value.</li></ul><h3 id="_17-medical-trial-eligibility-matcher" tabindex="-1">17. Medical Trial Eligibility Matcher <a class="header-anchor" href="#_17-medical-trial-eligibility-matcher" aria-label="Permalink to &quot;17. Medical Trial Eligibility Matcher&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Oncologists/Doctors trying to find clinical trials for patients.</li><li><strong>Bottleneck:</strong> Matching unstructured patient records (EHR) against complex, unstructured inclusion/exclusion criteria on ClinicalTrials.gov.</li><li><strong>Agentic Necessity:</strong> Needs to extract patient conditions, query the ClinicalTrials API, read complex logic (&quot;must have X but not Y unless Z&quot;), and explain the match.</li><li><strong>Baseline:</strong> Keyword search on ClinicalTrials.gov.</li><li><strong>Primary Metric:</strong> Precision/Recall of eligible trials.</li><li><strong>10+ Cases Feasibility:</strong> High (synthetic patient profiles).</li><li><strong>Verification:</strong> Review by a medical professional (or gold-standard dataset).</li><li><strong>Data Availability:</strong> ClinicalTrials.gov API + Synthetic EHR data (MIMIC-III).</li><li><strong>Engineering Depth:</strong> High (complex logical reasoning).</li><li><strong>Reproducibility:</strong> High.</li><li><strong>Differentiation:</strong> Solves a highly complex, life-saving logical mapping problem.</li><li><strong>Risks:</strong> Hallucinations in medical context.</li><li><strong>Demo Potential:</strong> Extremely high impact.</li><li><strong>Rubric Strengths/Weaknesses:</strong> Excellent User Value and Baseline comparison.</li></ul><h3 id="_18-grant-application-compliance-checker" tabindex="-1">18. Grant Application Compliance Checker <a class="header-anchor" href="#_18-grant-application-compliance-checker" aria-label="Permalink to &quot;18. Grant Application Compliance Checker&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Academic researchers submitting grants (e.g., to NIH or NSF).</li><li><strong>Bottleneck:</strong> Grants are rejected for trivial formatting issues, missing specific sections, or failing to address specific rubric points in a 100-page PDF.</li><li><strong>Agentic Necessity:</strong> Needs to read the agency&#39;s solicitation PDF, read the user&#39;s draft, and meticulously check every constraint (margins, sections, data management plans).</li><li><strong>Baseline:</strong> Simple LLM review (misses structural constraints).</li><li><strong>Primary Metric:</strong> Number of valid compliance errors caught.</li><li><strong>10+ Cases Feasibility:</strong> Medium (needs 10 mock grant proposals).</li><li><strong>Verification:</strong> Compare to agency rejection criteria.</li><li><strong>Data Availability:</strong> Public grant guidelines, hard to find realistic drafts.</li><li><strong>Engineering Depth:</strong> Medium.</li><li><strong>Reproducibility:</strong> High.</li><li><strong>Rubric Strengths/Weaknesses:</strong> Good, but data acquisition for 10 cases is annoying.</li></ul><hr><h2 id="domain-business-operations-data-finance" tabindex="-1">Domain: Business Operations, Data &amp; Finance <a class="header-anchor" href="#domain-business-operations-data-finance" aria-label="Permalink to &quot;Domain: Business Operations, Data &amp; Finance&quot;">​</a></h2><h3 id="_19-invoice-reconciliation-agent-accounts-payable" tabindex="-1">19. Invoice Reconciliation Agent (Accounts Payable) <a class="header-anchor" href="#_19-invoice-reconciliation-agent-accounts-payable" aria-label="Permalink to &quot;19. Invoice Reconciliation Agent (Accounts Payable)&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Accountants matching invoices to purchase orders and bank statements.</li><li><strong>Bottleneck:</strong> Dealing with OCR errors, different currencies, missing line items, and differing supplier formats.</li><li><strong>Agentic Necessity:</strong> Needs to read PDFs (vision), query the ERP system (API), calculate totals, and flag discrepancies.</li><li><strong>Baseline:</strong> Traditional OCR templates (break when layout changes).</li><li><strong>Primary Metric:</strong> Percentage of invoices successfully reconciled without human intervention.</li><li><strong>10+ Cases Feasibility:</strong> High (can generate synthetic invoices and POs).</li><li><strong>Verification:</strong> Absolute mathematical accuracy.</li><li><strong>Data Availability:</strong> Synthetic data generation is easy.</li><li><strong>Engineering Depth:</strong> Medium.</li><li><strong>Reproducibility:</strong> High.</li><li><strong>Differentiation:</strong> Layout-agnostic, handles fuzzy logic (e.g., &quot;Dozen Apples&quot; vs &quot;12x Apples&quot;).</li><li><strong>Risks:</strong> Boring demo.</li><li><strong>Rubric Strengths/Weaknesses:</strong> Extremely clear Baseline and Evaluation metric.</li></ul><h3 id="_20-supply-chain-risk-monitor" tabindex="-1">20. Supply Chain Risk Monitor <a class="header-anchor" href="#_20-supply-chain-risk-monitor" aria-label="Permalink to &quot;20. Supply Chain Risk Monitor&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Supply chain managers tracking global shipments.</li><li><strong>Bottleneck:</strong> Realizing a shipment will be late requires monitoring weather, news (port strikes), and logistics APIs simultaneously.</li><li><strong>Agentic Necessity:</strong> Needs to monitor a list of shipments, search live news for disruptions at transit nodes, and calculate delay probabilities.</li><li><strong>Baseline:</strong> Standard logistics tracking API (only updates when a scan is missed).</li><li><strong>Primary Metric:</strong> Advance warning time for disruptions.</li><li><strong>10+ Cases Feasibility:</strong> Medium (requires simulating live news).</li><li><strong>Verification:</strong> Historical backtesting.</li><li><strong>Data Availability:</strong> Difficult to package for reproducible judging.</li><li><strong>Engineering Depth:</strong> High.</li><li><strong>Risks:</strong> Fails Reproducibility (relies on live external changing data).</li></ul><h3 id="_21-e-commerce-product-catalog-normalizer" tabindex="-1">21. E-commerce Product Catalog Normalizer <a class="header-anchor" href="#_21-e-commerce-product-catalog-normalizer" aria-label="Permalink to &quot;21. E-commerce Product Catalog Normalizer&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Retailers importing products from hundreds of different vendors.</li><li><strong>Bottleneck:</strong> Vendors provide messy CSVs. One says &quot;Color: Blk&quot;, another says &quot;Colour: Black&quot;. Mapping these to a standard taxonomy is entirely manual.</li><li><strong>Agentic Necessity:</strong> Needs to read supplier CSVs, search the internet to figure out what ambiguous products are, and map them to a strict JSON schema.</li><li><strong>Baseline:</strong> Simple Python script with dictionaries/regex.</li><li><strong>Primary Metric:</strong> Categorization accuracy.</li><li><strong>10+ Cases Feasibility:</strong> High (messy CSVs).</li><li><strong>Verification:</strong> Compare to human-normalized catalogs.</li><li><strong>Data Availability:</strong> Easy to synthesize or scrape.</li><li><strong>Engineering Depth:</strong> Medium.</li><li><strong>Reproducibility:</strong> High.</li><li><strong>Differentiation:</strong> Uses web search to resolve ambiguity (e.g., &quot;Model XJ-9&quot; -&gt; searches web -&gt; &quot;Oh, it&#39;s a toaster&quot; -&gt; Category: Appliances).</li><li><strong>Rubric Strengths/Weaknesses:</strong> Very solid, reproducible, clear baseline.</li></ul><h3 id="_22-seo-competitor-content-gap-analyzer" tabindex="-1">22. SEO Competitor Content Gap Analyzer <a class="header-anchor" href="#_22-seo-competitor-content-gap-analyzer" aria-label="Permalink to &quot;22. SEO Competitor Content Gap Analyzer&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Marketing teams trying to outrank competitors.</li><li><strong>Bottleneck:</strong> Reading top 10 Google results and figuring out what topics they cover that your article misses.</li><li><strong>Agentic Necessity:</strong> Needs to execute Google searches, scrape 10 articles, build a knowledge graph of topics, and compare it to the user&#39;s draft.</li><li><strong>Baseline:</strong> Ahrefs/Clearscope (expensive, uses basic TF-IDF).</li><li><strong>Primary Metric:</strong> Number of highly relevant semantic topics identified.</li><li><strong>10+ Cases Feasibility:</strong> High.</li><li><strong>Verification:</strong> Subjective review of the recommendations.</li><li><strong>Data Availability:</strong> The web.</li><li><strong>Engineering Depth:</strong> Medium (scraping, summarization).</li><li><strong>Reproducibility:</strong> Medium (search results change over time).</li><li><strong>Rubric Strengths/Weaknesses:</strong> Weak on objective metrics (evaluation is subjective).</li></ul><h3 id="_23-customer-support-ticket-escalation-predictor" tabindex="-1">23. Customer Support Ticket Escalation Predictor <a class="header-anchor" href="#_23-customer-support-ticket-escalation-predictor" aria-label="Permalink to &quot;23. Customer Support Ticket Escalation Predictor&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> CS Managers trying to prevent customer churn.</li><li><strong>Bottleneck:</strong> By the time a ticket is flagged as &quot;angry&quot;, the customer is already churning.</li><li><strong>Agentic Necessity:</strong> Needs to analyze the back-and-forth history, cross-reference with the customer&#39;s previous tickets, and suggest preemptive compensation.</li><li><strong>Baseline:</strong> Sentiment analysis script (flags bad words).</li><li><strong>Primary Metric:</strong> Correlation with actual escalations (using historical data).</li><li><strong>10+ Cases Feasibility:</strong> High.</li><li><strong>Data Availability:</strong> Synthetic Zendesk tickets.</li><li><strong>Engineering Depth:</strong> Low-Medium.</li><li><strong>Rubric Strengths/Weaknesses:</strong> Weak Agentic Necessity (mostly just text classification).</li></ul><h3 id="_24-sec-filing-risk-factor-analyzer-finance" tabindex="-1">24. SEC Filing Risk Factor Analyzer (Finance) <a class="header-anchor" href="#_24-sec-filing-risk-factor-analyzer-finance" aria-label="Permalink to &quot;24. SEC Filing Risk Factor Analyzer (Finance)&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Equity analysts reading 10-K reports.</li><li><strong>Bottleneck:</strong> Finding the <em>new</em> risks added this year compared to last year&#39;s 10-K, hidden in 200 pages of boilerplate.</li><li><strong>Agentic Necessity:</strong> Needs to fetch both PDFs, align the text, ignore boilerplate changes, and summarize the material shifts in business risk.</li><li><strong>Baseline:</strong> Standard PDF text diff (useless due to formatting changes).</li><li><strong>Primary Metric:</strong> Precision of material risk changes identified.</li><li><strong>10+ Cases Feasibility:</strong> High (EDGAR).</li><li><strong>Reproducibility:</strong> High.</li><li><strong>Rubric Strengths/Weaknesses:</strong> Good, but highly specialized.</li></ul><hr><h2 id="domain-content-hr-miscellaneous" tabindex="-1">Domain: Content, HR &amp; Miscellaneous <a class="header-anchor" href="#domain-content-hr-miscellaneous" aria-label="Permalink to &quot;Domain: Content, HR &amp; Miscellaneous&quot;">​</a></h2><h3 id="_25-podcast-video-localization-reviewer" tabindex="-1">25. Podcast/Video Localization Reviewer <a class="header-anchor" href="#_25-podcast-video-localization-reviewer" aria-label="Permalink to &quot;25. Podcast/Video Localization Reviewer&quot;">​</a></h3><p><em>(Note: This is one of the Micro1 examples, included for completeness)</em></p><ul><li><strong>User/Problem:</strong> Media teams dubbing/translating podcasts.</li><li><strong>Bottleneck:</strong> Ensuring tone, speaker identity, and recurring jokes are consistent across 50 episodes in 5 languages.</li><li><strong>Agentic Necessity:</strong> Needs to maintain a glossary across episodes, check new transcripts against the glossary, and enforce tone.</li><li><strong>Baseline:</strong> Zero-shot translation of a single episode.</li><li><strong>Primary Metric:</strong> Consistency errors caught.</li><li><strong>Reproducibility:</strong> High (using fixed audio/text files).</li></ul><h3 id="_26-hr-resume-vs-job-description-bias-fact-checker" tabindex="-1">26. HR Resume vs Job Description Bias &amp; Fact Checker <a class="header-anchor" href="#_26-hr-resume-vs-job-description-bias-fact-checker" aria-label="Permalink to &quot;26. HR Resume vs Job Description Bias &amp; Fact Checker&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Recruiters spending 10 seconds per resume.</li><li><strong>Bottleneck:</strong> Missing great candidates because they didn&#39;t use exact keywords, or passing fake candidates who just copy-pasted the JD.</li><li><strong>Agentic Necessity:</strong> Needs to verify claims (e.g., &quot;Led project X&quot; -&gt; check public LinkedIn/GitHub if authorized), and map latent skills to the JD.</li><li><strong>Baseline:</strong> ATS Keyword matching.</li><li><strong>Primary Metric:</strong> Precision of skill mapping.</li><li><strong>10+ Cases Feasibility:</strong> High (synthetic resumes).</li><li><strong>Reproducibility:</strong> High.</li><li><strong>Rubric Strengths/Weaknesses:</strong> Good, but verification via web search can be flaky.</li></ul><h3 id="_27-meeting-action-item-follow-up-orchestrator" tabindex="-1">27. Meeting Action Item Follow-up Orchestrator <a class="header-anchor" href="#_27-meeting-action-item-follow-up-orchestrator" aria-label="Permalink to &quot;27. Meeting Action Item Follow-up Orchestrator&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Project managers chasing people for updates.</li><li><strong>Bottleneck:</strong> Extracting tasks from transcripts, putting them in Jira, and messaging people on Slack 3 days later.</li><li><strong>Agentic Necessity:</strong> Needs to parse transcripts, create tickets, wait (memory/state), check Jira status 3 days later, and draft Slack pings if incomplete.</li><li><strong>Baseline:</strong> Basic transcript-to-bullet-points summarization.</li><li><strong>Primary Metric:</strong> Tasks successfully tracked end-to-end.</li><li><strong>Reproducibility:</strong> Very Hard (requires mocking time, Slack, and Jira for the judges).</li><li><strong>Rubric Strengths/Weaknesses:</strong> Fails Reproducibility and End-to-End Execution for judging purposes.</li></ul><h3 id="_28-real-estate-zoning-permit-analyzer" tabindex="-1">28. Real Estate Zoning &amp; Permit Analyzer <a class="header-anchor" href="#_28-real-estate-zoning-permit-analyzer" aria-label="Permalink to &quot;28. Real Estate Zoning &amp; Permit Analyzer&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Real estate developers assessing a plot of land.</li><li><strong>Bottleneck:</strong> Reading hundreds of pages of municipal zoning codes to answer &quot;Can I build a 4-story duplex here?&quot;</li><li><strong>Agentic Necessity:</strong> Needs to query GIS databases for the parcel, fetch the specific city&#39;s zoning PDF, and execute spatial/logical reasoning.</li><li><strong>Baseline:</strong> RAG on the zoning code.</li><li><strong>Primary Metric:</strong> Accuracy of the final &quot;Yes/No + Constraints&quot; answer.</li><li><strong>10+ Cases Feasibility:</strong> High.</li><li><strong>Reproducibility:</strong> High (if PDFs are downloaded and bundled).</li><li><strong>Differentiation:</strong> High value, niche, complex reasoning.</li></ul><h3 id="_29-local-dev-environment-troubleshooter" tabindex="-1">29. Local Dev Environment Troubleshooter <a class="header-anchor" href="#_29-local-dev-environment-troubleshooter" aria-label="Permalink to &quot;29. Local Dev Environment Troubleshooter&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> New developers onboarding and getting &quot;Module Not Found&quot; or &quot;Docker failed to bind&quot; errors.</li><li><strong>Bottleneck:</strong> Bothering senior engineers for environment setup issues.</li><li><strong>Agentic Necessity:</strong> Needs to run shell commands (<code>env</code>, <code>docker ps</code>, <code>npm list</code>), read configurations, and apply fixes iteratively until the app starts.</li><li><strong>Baseline:</strong> Searching the error on Google.</li><li><strong>Primary Metric:</strong> Time to successful app launch.</li><li><strong>10+ Cases Feasibility:</strong> Medium (requires building 10 broken Docker environments).</li><li><strong>Reproducibility:</strong> High (via Dockerized broken states).</li><li><strong>Differentiation:</strong> Acts in the terminal iteratively.</li><li><strong>Rubric Strengths/Weaknesses:</strong> High Agentic Necessity, excellent demo.</li></ul><h3 id="_30-ux-ui-consistency-auditor-figma-to-code" tabindex="-1">30. UX/UI Consistency Auditor (Figma to Code) <a class="header-anchor" href="#_30-ux-ui-consistency-auditor-figma-to-code" aria-label="Permalink to &quot;30. UX/UI Consistency Auditor (Figma to Code)&quot;">​</a></h3><ul><li><strong>User/Problem:</strong> Designers/Frontend devs ensuring the coded app matches the Figma design.</li><li><strong>Bottleneck:</strong> Visually hunting for wrong padding, wrong fonts, or incorrect hex codes.</li><li><strong>Agentic Necessity:</strong> Needs to extract design tokens from Figma API, take screenshots of the live local app, and compare them visually and via CSS inspection.</li><li><strong>Baseline:</strong> Pixel-diffing tools (fail on responsive changes).</li><li><strong>Primary Metric:</strong> Semantic design deviations caught (e.g., &quot;Uses #333 instead of #000&quot;).</li><li><strong>10+ Cases Feasibility:</strong> High.</li><li><strong>Reproducibility:</strong> High.</li><li><strong>Differentiation:</strong> Combines vision with API data to do semantic design review.</li><li><strong>Rubric Strengths/Weaknesses:</strong> Extremely cool, visually impressive demo, high technical depth.</li></ul>',73)])])}const m=e(n,[["render",o]]);export{h as __pageData,m as default};
